<script setup>
import {unitLabel} from './units'
import WorkspaceBar from './components/WorkspaceBar.vue'
import {sidebarCollapsed} from './workspace'
import {computed,nextTick,onMounted,reactive,ref,watch} from 'vue'
import {call,setCSRF} from './api'
import DataTable from './components/DataTable.vue'
import LinkPicker from './components/LinkPicker.vue'
import WarehousePlanning from './components/WarehousePlanning.vue'
import {dismissOnBackdrop} from './dialogs'
import {Button as UiButton} from './components/ui/button'
import {Input as UiInput} from './components/ui/input'
import {Textarea as UiTextarea} from './components/ui/textarea'
import {Card as UiCard} from './components/ui/card'
import UiSelect from './components/ui/select/Select.vue'

const masterAPI=(name,args={},write=false)=>call('lotus_farm.warehouse_masters.'+name,args,write)
const api=(name,args={},write=false)=>call('lotus_farm.warehouse.'+name,args,write)
const session=ref(null),data=ref(null),company=ref(''),warehouse=ref(''),search=ref(''),start=ref(0),tab=ref('stock')
const sortStock=ref([]),sortMovement=ref([]),sortDocument=ref([])
const columnFilters=ref({}),demandFrom=ref(''),demandTo=ref('')
const movementData=ref(null),movementFilters=ref({}),movementStart=ref(0),movementFrom=ref(''),movementTo=ref('')
const documentData=ref(null),documentFilters=ref({}),planningView=ref(null)
const busy=ref(false),saving=ref(false),error=ref(''),saved=ref(null),dialog=ref(null)
const masterEditing=ref(null),masterDeleting=ref(false),masterLists=ref({groups:[],warehouses:[]}),draftDeleting=ref(false)
const masterClearDefaults=ref(false)
const masterDialog=ref(null),masterKind=ref('item'),masterBusy=ref(false),masterError=ref(''),catalog=ref({groups:[],uoms:[],parents:[]})
const hrEmployees=ref([])
const master=reactive({name:'',code:'',group:'',uom:'',parent:'',description:'',new_group:'',group_parent:'',minimum_warehouse:'',minimum_stock:0,lotus_address:'',lotus_contact_employee:'',lotus_contact_name:'',lotus_contact_phone:'',lotus_receiving_hours:'',lotus_default_lead_days:0,lotus_delivery_note:''})
const warehouseCode=computed(()=>{const n=String(master.name||'').trim();const abbr=session.value?.companies.find(c=>c.name===company.value)?.abbr;return n&&abbr?(n.endsWith(' - '+abbr)?n:n+' - '+abbr):n})
const employeeName=id=>hrEmployees.value.find(e=>e.value===id)?.label||''
async function loadHREmployees(){hrEmployees.value=await masterAPI('employee_choices',{company:company.value})}
const masterTitles={item:'Thêm vật tư',group:'Thêm nhóm vật tư',warehouse:'Thêm kho'}
const commonUnits={Kg:'kg',Gram:'g',Litre:'Lít',Millilitre:'ml',Nos:'Cái',Box:'Hộp / thùng',Pair:'Đôi',Meter:'Mét',Tonne:'Tấn',Unit:'Đơn vị'}
const popularUoms=computed(()=>Object.keys(commonUnits).filter(name=>catalog.value.uoms.some(u=>u.name===name)))
const detailDialog=ref(null),detail=ref(null),detailError=ref(''),posting=ref(false),confirmPost=ref(false)
const kinds={receipt:'Nhập kho',issue:'Xuất dùng',transfer:'Chuyển kho',count:'Kiểm kê'}
const form=reactive({kind:'receipt',count_purpose:'Stock Reconciliation',posting_date:'',source:'',target:'',notes:'',lines:[],issue_mode:'Manual',work_plan:'',receiver:'',receiver_employee:'',additional_costs:[],existing_name:'',base_modified:'',client_event_id:''})
const issueTabs={Manual:'Thủ công',Plan:'Theo kế hoạch đã duyệt',Request:'Theo yêu cầu đã duyệt'}
const issueSources=ref([]),issueSource=ref(''),issueNote=ref(''),issueLoading=ref(false)
let issueVersion=0
const fmt=n=>Number(n||0).toLocaleString('vi-VN',{maximumFractionDigits:3})
const needsSource=computed(()=>['issue','transfer'].includes(form.kind))
const needsTarget=computed(()=>['receipt','transfer','count'].includes(form.kind))
const canCreate=computed(()=>!!company.value&&!!data.value?.warehouses.length)
const stocks=computed(()=>data.value?.items||[])
const money=computed(()=>data.value?.currency||'VND')
const cash=n=>Number(n||0).toLocaleString('vi-VN',{style:'currency',currency:money.value})
const warehouseLabel=id=>data.value?.warehouses?.find(w=>w.name===id)?.warehouse_name||id||'—'
const receiptAccounts=ref([]),costAccount=ref(''),costLoading=ref(false)
const receiptBasic=computed(()=>form.lines.reduce((sum,row)=>sum+Number(row.qty||0)*Number(row.rate||0),0))
const receiptCharges=computed(()=>form.additional_costs.reduce((sum,row)=>sum+Number(row.amount||0),0))
async function loadReceiptAccounts(){costLoading.value=true;try{const result=await api('receipt_accounts',{company:company.value});receiptAccounts.value=result.accounts;costAccount.value=result.default_account||''}catch(e){error.value=e.message}finally{costLoading.value=false}}
function addCost(){form.additional_costs.push({description:'',amount:0,expense_account:costAccount.value})}

let version=0
async function refresh(reset=false){
 if(reset){start.value=0;movementStart.value=0}
 if(!company.value){data.value=null;return}
 const request=++version;busy.value=true;error.value=''
 try{const result=await api('overview',{company:company.value,warehouse:warehouse.value,search:tab.value==='stock'?search.value:'',start:start.value,sort_model:JSON.stringify(sortStock.value),column_filters:JSON.stringify(columnFilters.value),from_date:demandFrom.value,to_date:demandTo.value});if(request!==version)return;data.value=result;if(tab.value==='movements'){const ledger=await api('movements',{company:company.value,warehouse:warehouse.value,search:search.value,from_date:movementFrom.value,to_date:movementTo.value,start:movementStart.value,sort_model:JSON.stringify(sortMovement.value),column_filters:JSON.stringify(movementFilters.value)});if(request===version)movementData.value=ledger}if(tab.value==='history'){const records=await api('documents',{company:company.value,warehouse:warehouse.value,search:search.value,from_date:movementFrom.value,to_date:movementTo.value,start:movementStart.value,sort_model:JSON.stringify(sortDocument.value),column_filters:JSON.stringify(documentFilters.value)});if(request===version)documentData.value=records}}
 catch(e){if(request===version){if(tab.value==='movements')movementData.value=null;else if(tab.value==='history')documentData.value=null;else data.value=null;error.value=e.message}}
 finally{if(request===version)busy.value=false}
}
async function initialize(){busy.value=true;try{session.value=await api('bootstrap');setCSRF(session.value.csrf_token);company.value=session.value.companies[0]?.name||'';form.posting_date=session.value.today;demandFrom.value=session.value.today;demandTo.value=session.value.today;await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
function companyChanged(){columnFilters.value={};movementFilters.value={};documentFilters.value={};documentData.value=null;movementData.value=null;warehouse.value='';saved.value=null;data.value=null;refresh(true)}
async function open(kind){if(kind==='issue'){try{await loadHREmployees()}catch(e){error.value=e.message;return}}issueVersion++;error.value='';saved.value=null;form.kind=kind;form.client_event_id=crypto.randomUUID();form.issue_mode='Manual';form.work_plan='';form.receiver='';form.receiver_employee='';issueSource.value='';issueSources.value=[];issueNote.value='';issueLoading.value=false;form.count_purpose='Stock Reconciliation';form.posting_date=session.value.today;form.source=warehouse.value||data.value.warehouses[0]?.name||'';form.target=kind==='transfer'?'':form.source;form.notes='';form.existing_name='';form.base_modified='';form.additional_costs=[];form.lines=[{item:'',qty:kind==='count'?0:1,area:'',rate:0}];await nextTick();dialog.value.showModal();if(kind==='receipt')await loadReceiptAccounts()}
async function searchItems(search){const result=await api('overview',{company:company.value,warehouse:warehouse.value,search});return result.items.map(item=>({value:item.name,label:item.item_name,uom:item.stock_uom,actual_qty:item.actual_qty}))}
function selectStockItem(row,option){row.item_name=option.label;row.uom=option.uom;row.actual_qty=option.actual_qty;chooseItem(row)}
function chooseItem(row){const item=stocks.value.find(i=>i.name===row.item);if(form.kind==='count'&&warehouse.value)row.qty=item?.actual_qty??row.actual_qty??0}
async function changeIssueMode(mode){const version=++issueVersion;form.issue_mode=mode;form.work_plan='';issueSource.value='';issueSources.value=[];issueNote.value='';error.value='';form.lines=mode==='Manual'?[{item:'',qty:1,area:''}]:[];issueLoading.value=mode!=='Manual';if(mode==='Manual')return;try{const result=await api('issue_sources',{company:company.value,mode});if(version===issueVersion){issueSources.value=result.rows;issueNote.value=result.note}}catch(e){if(version===issueVersion)error.value=e.message}finally{if(version===issueVersion)issueLoading.value=false}}
async function selectIssueSource(){const version=++issueVersion;form.lines=[];form.work_plan=form.issue_mode==='Plan'?issueSource.value:'';if(!issueSource.value)return;issueLoading.value=true;error.value='';try{const result=await api('issue_lines',{company:company.value,mode:form.issue_mode,name:issueSource.value});if(version===issueVersion){form.lines=result.rows.map(r=>({...r,qty:r.remaining_qty,fixed_area:!!r.area}));issueNote.value=result.note}}catch(e){if(version===issueVersion)error.value=e.message}finally{if(version===issueVersion)issueLoading.value=false}}
async function save(){
 if(saving.value)return
 saving.value=true;error.value=''
 try{const lines=form.kind==='issue'&&form.issue_mode!=='Manual'?form.lines.filter(r=>Number(r.qty)>0):form.lines;if(!lines.length)throw new Error('Chọn ít nhất một dòng vật tư có số lượng cấp lớn hơn 0.');saved.value=await api('create_draft',{company:company.value,...form,lines},true);dialog.value.close();tab.value='history';await refresh();await openDocument(saved.value.doctype,saved.value.name)}
 catch(e){error.value=e.message}
 finally{saving.value=false}
}
const status=s=>['Nháp','Đã ghi sổ','Đã hủy'][s]||s
const type=t=>({'Material Receipt':'Nhập kho','Material Issue':'Xuất dùng','Material Transfer':'Chuyển kho','Repack':'Đóng gói','Opening Stock':'Tồn đầu kỳ','Stock Reconciliation':'Kiểm kê'})[t]||t
async function openMaster(kind){
 if(kind==='warehouse'){try{await loadHREmployees()}catch(e){error.value=e.message;return}}
 masterError.value='';error.value='';masterKind.value=kind;masterEditing.value=null;masterDeleting.value=false;masterClearDefaults.value=false
 try{catalog.value=await api('catalogue',{company:company.value});const root=catalog.value.groups.find(g=>g.is_group&&!g.parent_item_group)?.name||catalog.value.groups.find(g=>g.is_group)?.name||''
 Object.assign(master,{name:'',code:'',group:'',uom:catalog.value.uoms.find(u=>u.name==='Kg')?.name||catalog.value.uoms[0]?.name||'',parent:kind==='warehouse'?catalog.value.parents[0]?.name||'':root,description:'',new_group:'',group_parent:root,minimum_warehouse:warehouse.value||data.value?.warehouses[0]?.name||'',minimum_stock:0,lotus_address:'',lotus_contact_employee:'',lotus_contact_name:'',lotus_contact_phone:'',lotus_receiving_hours:'',lotus_default_lead_days:0,lotus_delivery_note:''});await nextTick();masterDialog.value.showModal()}
 catch(e){error.value=e.message}
}
async function saveMaster(){if(masterBusy.value)return;masterBusy.value=true;masterError.value=''
 try{const result=masterEditing.value?await masterAPI('save_master',{company:company.value,kind:masterKind.value,name:masterEditing.value.id,modified:masterEditing.value.modified,values:{...master}},true):await api('create_master',{company:company.value,kind:masterKind.value,values:{...master}},true);masterDialog.value.close();saved.value={name:result.name,master:true};if(masterKind.value==='item'){search.value='';start.value=0}await refresh();catalog.value=await api('catalogue',{company:company.value});await loadMasterLists()}
 catch(e){masterError.value=e.message}finally{masterBusy.value=false}
}
async function loadMasterLists(){if(!company.value)return;try{masterLists.value=await masterAPI('master_lists',{company:company.value})}catch(e){error.value=e.message}}
watch(tab,(value,previous)=>{if(value==='setup')loadMasterLists();if(['movements','history'].includes(value)||['movements','history'].includes(previous)){search.value='';refresh(true)}})
async function editMaster(kind,name){await openMaster(kind);try{const result=await masterAPI('read_master',{company:company.value,kind,name});masterEditing.value=result;Object.assign(master,{name:result.name,code:result.code,group:result.group||'',uom:result.uom||'',parent:result.parent||'',description:result.description||'',minimum_warehouse:warehouse.value||data.value?.warehouses[0]?.name||'',minimum_stock:0,...Object.fromEntries(['lotus_address','lotus_contact_employee','lotus_contact_name','lotus_contact_phone','lotus_receiving_hours','lotus_default_lead_days','lotus_delivery_note'].map(k=>[k,result[k]]))});master.minimum_stock=result.minimum_levels[master.minimum_warehouse]||0}catch(e){masterError.value=e.message}}
async function deleteMaster(){if(!masterEditing.value||masterBusy.value)return;masterBusy.value=true;try{await masterAPI('delete_master',{company:company.value,kind:masterKind.value,name:masterEditing.value.id,modified:masterEditing.value.modified,clear_defaults:masterClearDefaults.value},true);masterDialog.value.close();saved.value=null;await refresh();await loadMasterLists()}catch(e){masterError.value=e.message}finally{masterBusy.value=false}}
async function editDocument(){const current=detail.value;detailDialog.value.close();const kind={'Material Receipt':'receipt','Material Issue':'issue','Material Transfer':'transfer'}[current.kind]||'count';await open(kind);Object.assign(form,{existing_name:current.name,base_modified:current.modified,posting_date:current.posting_date,count_purpose:current.kind,source:current.items[0]?.source||'',target:current.items[0]?.target||'',notes:current.notes||'',receiver:current.receiver||'',receiver_employee:current.receiver_employee||'',issue_mode:current.issue_mode||'Manual',additional_costs:(current.additional_costs||[]).map(row=>({...row})),lines:current.items.map(row=>({...row,rate:row.rate||0}))})}
async function deleteDraft(){if(posting.value)return;posting.value=true;try{await api('delete_draft',{doctype:detail.value.doctype,name:detail.value.name,modified:detail.value.modified},true);detailDialog.value.close();saved.value=null;draftDeleting.value=false;await refresh()}catch(e){detailError.value=e.message}finally{posting.value=false}}
const groupColumns=[{field:'name',headerName:'Nhóm vật tư'},{field:'parent_item_group',headerName:'Nhóm cha'}]
const warehouseColumns=[{field:'warehouse_name',headerName:'Tên kho'},{field:'name',headerName:'Mã kho'},{field:'lotus_address',headerName:'Địa chỉ kho',minWidth:220},{field:'lotus_contact_name',headerName:'Người phụ trách'},{field:'lotus_contact_phone',headerName:'Liên hệ'},{field:'lotus_default_lead_days',headerName:'Ngày chờ hàng mặc định'}]

async function openDocument(doctype,name){error.value='';detailError.value='';confirmPost.value=false;draftDeleting.value=false;try{detail.value=await api('document',{doctype,name});await nextTick();detailDialog.value.showModal()}catch(e){error.value=e.message}}
async function postDocument(){if(posting.value||!confirmPost.value)return;posting.value=true;detailError.value='';try{await api('submit_document',{doctype:detail.value.doctype,name:detail.value.name,modified:detail.value.modified},true);detail.value=await api('document',{doctype:detail.value.doctype,name:detail.value.name});confirmPost.value=false;await refresh()}catch(e){detailError.value=e.message}finally{posting.value=false}}

const stockNumber=(field,headerName,minWidth=100)=>({field,headerName,minWidth,type:'numericColumn',valueFormatter:p=>p.value==null?'—':fmt(p.value)})
const stockColumns=[{field:'name',valueGetter:p=>p.data.item_name,headerName:'Vật tư',minWidth:200,flex:1.6,cellRenderer:itemCell,tooltipValueGetter:p=>p.data.item_name+' · '+p.data.name,mobileValue:r=>r.item_name+' · '+r.name},{field:'stock_uom',headerName:'Đơn vị',minWidth:65,valueFormatter:p=>unitLabel(p.value)},stockNumber('actual_qty','Tồn thực tế',100),stockNumber('demand_qty','Nhu cầu',90),stockNumber('available_qty','Tồn khả dụng',115),stockNumber('demand_shortage_qty','Thiếu',80),stockNumber('incoming_qty','Đang chờ nhập',120),stockNumber('to_buy_qty','Cần mua thêm',120),{field:'coverage_status',headerName:'Trạng thái',minWidth:130,cellClass:p=>'lotus-coverage-state '+({'Đủ hàng':'is-covered','Chờ nhập':'is-incoming','Cần mua':'is-short'}[p.value]||'')},{field:'item_group',headerName:'Nhóm',minWidth:105},stockNumber('minimum_stock','Tối thiểu',85),stockNumber('shortage_qty','Thiếu tối thiểu',115),{field:'stock_status',headerName:'Cảnh báo tồn',minWidth:120}]

const historyRows=computed(()=>documentData.value?.rows||[])
const historyColumns=[{field:'name',headerName:'Mã phiếu',minWidth:230,flex:2},{field:'kind',headerName:'Nghiệp vụ'},{field:'posting_date',headerName:'Ngày'},{field:'warehouses',headerName:'Kho',minWidth:200},{field:'docstatus',headerName:'Trạng thái phiếu',valueFormatter:p=>status(p.value)}]
function filterDocument({field,values}){const next={...documentFilters.value};if(values===null)delete next[field];else next[field]=values;documentFilters.value=next;refresh(true)}
const movementColumns=[{field:'posting_date',headerName:'Ngày',minWidth:95},{field:'item_code',headerName:'Vật tư',minWidth:200,flex:1.6,valueFormatter:p=>p.data?p.data.item_name+' · '+p.value:p.value},{field:'warehouse',headerName:'Kho',minWidth:130,valueFormatter:p=>warehouseLabel(p.value)},{field:'opening_qty',headerName:'Tồn đầu',minWidth:80,type:'numericColumn',valueFormatter:p=>fmt(p.value)},{field:'in_qty',headerName:'Nhập',minWidth:75,type:'numericColumn',valueFormatter:p=>fmt(p.value)},{field:'out_qty',headerName:'Xuất',minWidth:75,type:'numericColumn',valueFormatter:p=>fmt(p.value)},{field:'qty_after_transaction',headerName:'Tồn cuối',minWidth:85,type:'numericColumn',valueFormatter:p=>fmt(p.value)},{field:'stock_uom',headerName:'Đơn vị',minWidth:65,valueFormatter:p=>unitLabel(p.value)},{field:'voucher_no',headerName:'Mã phiếu',minWidth:170},{field:'kind',headerName:'Biến động',minWidth:95}]
async function openStockDocument(doctype,name){if(doctype==='Purchase Receipt'){tab.value='planning';await nextTick();await planningView.value?.openReceipt(name)}else await openDocument(doctype,name)}
function openMovement(row){if(['Stock Entry','Stock Reconciliation','Purchase Receipt'].includes(row.voucher_type))openStockDocument(row.voucher_type,row.voucher_no);else error.value='Loại phiếu này chưa có form chi tiết trong màn hình kho.'}
const printURL=(doctype,name)=>'/lotus/in-phieu?'+new URLSearchParams({doctype,name})
const detailColumns=[{headerName:'Vật tư',minWidth:220,flex:2,valueGetter:p=>p.data.item_name||p.data.item},{field:'item',headerName:'Mã vật tư'},{field:'qty',headerName:'Số lượng',type:'numericColumn',valueFormatter:p=>fmt(p.value)},{field:'uom',headerName:'Đơn vị',valueFormatter:p=>unitLabel(p.value)},{field:'area',headerName:'Khu vực / lô'},{headerName:'Kho xuất / nhận',minWidth:220,valueGetter:p=>[p.data.source,p.data.target].filter(Boolean).map(warehouseLabel).join(' → ')}]

const receiptDetailColumns=[{field:'rate',headerName:'Đơn giá',type:'numericColumn',valueFormatter:p=>cash(p.value)},{field:'additional_cost',headerName:'Chi phí phân bổ',type:'numericColumn',valueFormatter:p=>cash(p.value)},{field:'amount',headerName:'Thành tiền',type:'numericColumn',valueFormatter:p=>cash(p.value)}]
onMounted(initialize)
function filterStock({field,values}){const next={...columnFilters.value};if(values===null)delete next[field];else next[field]=values;columnFilters.value=next;refresh(true)}
const stockTabs={stock:'Tồn kho',planning:'Nhu cầu & mua vật tư',history:'Phiếu nhập · xuất',movements:'Lịch sử nhập xuất',setup:'Thiết lập kho'}
const workspaceActions=computed(()=>[{id:'farm-work',label:'Công việc nông trường',navigation:true,href:'/lotus/cong-viec'},{id:'attendance',label:'Chấm công',navigation:true,href:'/lotus/cham-cong'},{id:'home',label:'Trang chủ Lotus',navigation:true,href:'/lotus/mobile'},...Object.entries(stockTabs).map(([id,label])=>({id,label,navigation:true,run:()=>tab.value=id})),...Object.entries(kinds).filter(([kind])=>canCreate.value&&session.value?.permissions[kind==='count'?'Stock Reconciliation':'Stock Entry']).map(([kind,label])=>({id:kind,label,run:()=>open(kind)})),...(session.value?.permissions.Item?[{id:'new-item',label:'Thêm vật tư',run:()=>openMaster('item')}]:[])])
function itemCell(params){const cell=document.createElement('span');cell.className='lotus-item-cell';for(const [cls,text] of [['name',params.data.item_name],['code',params.data.name]]){const span=document.createElement('span');span.className=cls;span.textContent=text;cell.append(span)}return cell}
</script>

<template>
 <div class="stock-shell" :class="{'sidebar-collapsed':sidebarCollapsed}">
  <aside class="stock-sidebar"><a class="stock-brand" href="/lotus/mobile"><img class="lotus-brand-image" :src="'/assets/lotus_farm/images/lotus-agritech.jpg'" alt="Lotus Agritech" width="707" height="411"></a><p class="stock-nav-label">KHÔNG GIAN LÀM VIỆC</p><nav aria-label="Quản lý kho"><UiButton variant="outline" :title="'Tồn kho'" aria-label="Tồn kho" :class="{selected:tab==='stock'}" @click="tab='stock'">▦ <span>Tồn kho</span></UiButton><UiButton variant="outline" title="Nhu cầu & mua vật tư" aria-label="Nhu cầu & mua vật tư" :class="{selected:tab==='planning'}" @click="tab='planning'">◎ <span>Nhu cầu & mua vật tư</span></UiButton><UiButton variant="outline" :title="'Phiếu nhập · xuất'" aria-label="Phiếu nhập · xuất" :class="{selected:tab==='history'}" @click="tab='history'">▤ <span>Phiếu nhập · xuất</span></UiButton><UiButton variant="outline" title="Lịch sử nhập xuất" aria-label="Lịch sử nhập xuất" :class="{selected:tab==='movements'}" @click="tab='movements'">↕ <span>Lịch sử nhập xuất</span></UiButton><UiButton variant="outline" :title="'Thiết lập kho'" aria-label="Thiết lập kho" :class="{selected:tab==='setup'}" @click="tab='setup'">⚙ <span>Thiết lập kho</span></UiButton></nav><div class="stock-sidebar-bottom"><a href="/lotus/mobile">← Về Lotus Farm</a><small>{{session?.user||'Đang kết nối…'}}</small></div></aside>
  <main class="stock-main"><WorkspaceBar :user="session?.user" :title="stockTabs[tab]" :actions="workspaceActions" />

   <p v-if="error&&!dialog?.open" class="stock-error" role="alert">{{error}}</p>
   <p v-if="saved" class="stock-success" role="status">{{saved.master?"Đã lưu danh mục":"Đã lưu nháp"}} <strong>{{saved.name}}</strong>. <UiButton variant="ghost" v-if="!saved.master" class="stock-text-button" @click="openDocument(saved.doctype,saved.name)">Xem phiếu →</UiButton></p>
   <div class="stock-scope"><label>Công ty<UiSelect v-model="company" @change="companyChanged"><option v-if="!session?.companies.length" value="">Chưa có công ty</option><option v-for="c in session?.companies" :key="c.name" :value="c.name">{{c.name}}</option></UiSelect></label><label>Kho<UiSelect v-model="warehouse" :disabled="!company||busy" @change="refresh(true)"><option value="">Tất cả kho được phân quyền</option><option v-for="w in data?.warehouses" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label><form v-if="['stock','movements','history'].includes(tab)" class="stock-search" @submit.prevent="refresh(true)"><UiInput v-model="search" aria-label="Tìm vật tư" :placeholder="tab==='stock'?'Tìm mã hoặc tên vật tư…':tab==='history'?'Tìm mã phiếu…':'Tìm vật tư hoặc mã phiếu…'" /><UiButton variant="outline" type="submit" class="stock-button" :disabled="busy||!company">Tìm</UiButton></form><UiButton variant="outline" class="stock-button" :disabled="busy" @click="tab==='planning'?planningView?.refresh():refresh()">{{busy?'Đang tải…':'↻ Làm mới'}}</UiButton></div>
   <section v-if="!busy&&session&&(!company||!data?.warehouses.length||!stocks.length)&&tab==='stock'" class="stock-welcome"><div class="stock-welcome-icon">▦</div><div><p class="stock-kicker">BẮT ĐẦU CHO FARM MỚI</p><h2>Kho mới, sẵn sàng từ bước đầu tiên.</h2><p>Tạo công ty, khai báo kho và vật tư. Khi hàng về, lập phiếu nhập để bắt đầu theo dõi tồn.</p><UiButton variant="default" class="stock-button primary" @click="tab='setup'">Thiết lập kho của bạn →</UiButton></div></section>
   <div v-if="tab==='stock'" class="stock-actions" aria-label="Thao tác kho"><UiButton variant="outline" v-for="(title,kind) in kinds" :key="kind" :disabled="!canCreate||!session?.permissions[kind==='count'?'Stock Reconciliation':'Stock Entry']||busy" @click="open(kind)"><span>{{{receipt:'↓',issue:'↑',transfer:'⇄',count:'✓'}[kind]}}</span><span>{{title}}</span></UiButton><UiButton variant="outline" v-if="session?.permissions.Item" class="stock-button" :disabled="!company" @click="openMaster('item')">+ Thêm vật tư</UiButton><UiButton v-if="Object.keys(columnFilters).length" variant="outline" @click="columnFilters={};refresh(true)">Bỏ bộ lọc ({{Object.keys(columnFilters).length}})</UiButton><UiButton variant="outline" @click="filterStock({field:'stock_status',values:['Dưới tối thiểu']})">Dưới tối thiểu</UiButton><div class="stock-summary" role="status"><span><strong>{{data?.warehouses.length??'—'}}</strong> kho</span><span><strong>{{data?.total_count??'—'}}</strong> vật tư</span><span><strong>{{data?.stocked_count??'—'}}</strong> có tồn</span></div></div>
   <template v-if="tab==='stock'">
    <div class="movement-filters"><label>Nhu cầu từ ngày<UiInput v-model="demandFrom" type="date" @change="refresh(true)"/></label><label>Đến ngày<UiInput v-model="demandTo" type="date" @change="refresh(true)"/></label><UiButton variant="outline" @click="filterStock({field:'coverage_status',values:['Cần mua','Chờ nhập']})">Thiếu theo nhu cầu</UiButton></div>
    <p v-for="warning in data?.coverage_warnings" :key="warning" class="stock-error" role="alert">{{warning}}</p>

    <section class="stock-panel"><DataTable :rows="stocks" :columns="stockColumns" server-sort @sort="model=>{sortStock=model;refresh(true)}" interactive @open="row=>editMaster('item',row.name)" :filter-values="data?.filter_values" :server-filters="columnFilters" @filter="filterStock" :loading="busy" :empty="search?'Không tìm thấy vật tư phù hợp.':'Chưa có vật tư. Thêm danh mục trong Thiết lập kho.'" /><footer class="stock-pagination"><span>Tối đa 50 vật tư / trang</span><div><UiButton variant="outline" class="stock-button" :disabled="!start||busy" @click="start-=50;refresh()">← Trước</UiButton><UiButton variant="outline" class="stock-button" :disabled="!data?.has_more||busy" @click="start+=50;refresh()">Sau →</UiButton></div></footer></section>
   </template>
   <WarehousePlanning v-if="tab==='planning'" ref="planningView" :company="company" :warehouse="warehouse" :today="session?.today"/>
   <div v-if="tab==='history'" class="movement-filters"><label>Từ ngày<UiInput v-model="movementFrom" type="date" @change="refresh(true)"/></label><label>Đến ngày<UiInput v-model="movementTo" type="date" @change="refresh(true)"/></label><UiButton v-if="Object.keys(documentFilters).length" variant="outline" @click="documentFilters={};refresh(true)">Bỏ bộ lọc</UiButton></div>
   <section v-if="tab==='history'" class="stock-panel"><DataTable :rows="historyRows" :columns="historyColumns" server-sort @sort="model=>{sortDocument=model;refresh(true)}" :loading="busy" :filter-values="documentData?.filter_values" :server-filters="documentFilters" @filter="filterDocument" interactive @open="row=>openStockDocument(row.doctype,row.name)"/><footer class="stock-pagination"><span>{{documentData?.total_count||0}} phiếu</span><div><UiButton variant="outline" :disabled="!movementStart||busy" @click="movementStart-=50;refresh()">← Trước</UiButton><UiButton variant="outline" :disabled="!documentData?.has_more||busy" @click="movementStart+=50;refresh()">Sau →</UiButton></div></footer></section>
   <template v-if="tab==='movements'">
    <div class="movement-filters"><label>Từ ngày<UiInput v-model="movementFrom" type="date" @change="refresh(true)"/></label><label>Đến ngày<UiInput v-model="movementTo" type="date" @change="refresh(true)"/></label><UiButton v-if="Object.keys(movementFilters).length" variant="outline" @click="movementFilters={};refresh(true)">Bỏ bộ lọc</UiButton><span>{{movementData?.total_count??0}} biến động đã ghi sổ</span></div>
    <section class="stock-panel"><DataTable :rows="movementData?.rows||[]" :columns="movementColumns" server-sort @sort="model=>{sortMovement=model;refresh(true)}" :loading="busy" :filter-values="movementData?.filter_values" :server-filters="movementFilters" @filter="filterMovement" interactive @open="openMovement" empty="Chưa có biến động đã ghi sổ trong phạm vi này."/><footer class="stock-pagination"><span>{{movementData?.total_count?movementStart+1:0}}–{{movementStart+(movementData?.rows.length||0)}} / {{movementData?.total_count||0}}</span><div><UiButton variant="outline" class="stock-button" :disabled="!movementStart||busy" @click="movementStart-=50;refresh()">← Trước</UiButton><UiButton variant="outline" class="stock-button" :disabled="!movementData?.has_more||busy" @click="movementStart+=50;refresh()">Sau →</UiButton></div></footer></section>
   </template>
   <section v-if="tab==='setup'" class="stock-setup">
    <UiCard><span>01</span><h2>Nhóm vật tư</h2><p>Phân bón, thuốc bảo vệ thực vật, bao bì, nông cụ… Gom vật tư để dễ tìm và theo dõi.</p><UiButton variant="outline" class="stock-button" :disabled="!company||!session?.permissions['Item Group']" @click="openMaster('group')">+ Thêm nhóm vật tư</UiButton></UiCard>
    <UiCard><span>02</span><h2>Danh mục vật tư</h2><p>Chỉ cần mã, tên, nhóm và đơn vị tính. Thêm xong có thể chọn ngay khi lập phiếu.</p><UiButton variant="outline" class="stock-button" :disabled="!company||!session?.permissions.Item" @click="openMaster('item')">+ Thêm vật tư</UiButton></UiCard>
    <UiCard><span>03</span><h2>Kho của farm</h2><p>Đặt tên kho dễ nhận biết. Kho mới thuộc công ty {{company||'đang chọn'}} và bắt đầu với tồn bằng 0.</p><UiButton variant="outline" class="stock-button" :disabled="!company||!session?.permissions.Warehouse" @click="openMaster('warehouse')">+ Thêm kho</UiButton></UiCard>
    <div class="stock-setup-note"><h3>{{company?'Công ty: '+company:'Chưa có công ty vận hành'}}</h3><p>{{company?'Tạo nhóm, thêm vật tư và kho ngay tại đây. Khi hàng về, chọn Nhập kho để ghi nhận.':'Cần cấu hình công ty vận hành trước khi tạo danh mục kho.'}}</p></div>
   </section><section v-if="tab==='setup'" class="master-list-grid"><div class="stock-panel"><DataTable :rows="masterLists.groups" :columns="groupColumns" interactive @open="row=>editMaster('group',row.name)"/></div><div class="stock-panel"><DataTable :rows="masterLists.warehouses" :columns="warehouseColumns" interactive @open="row=>editMaster('warehouse',row.name)"/></div></section>

  </main>
  <dialog @click="dismissOnBackdrop($event,saving)" ref="dialog" class="stock-dialog" @cancel="error=''">
   <form @submit.prevent="save"><header><div><h2>{{kinds[form.kind]}}</h2></div><UiButton variant="outline" type="button" class="stock-button" aria-label="Đóng" :disabled="saving" @click="dialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p>
    <section v-if="form.kind==='issue'" class="stock-issue-picker">
     <div class="stock-issue-tabs" role="tablist" aria-label="Hình thức xuất kho"><UiButton variant="outline" v-for="(title,mode) in issueTabs" :key="mode" type="button" role="tab" :aria-selected="form.issue_mode===mode" :class="{active:form.issue_mode===mode}" :disabled="saving" @click="changeIssueMode(mode)">{{title}}</UiButton></div>

     <label v-if="form.issue_mode!=='Manual'">{{form.issue_mode==='Plan'?'Kế hoạch đã duyệt':'Yêu cầu vật tư đã duyệt'}}<UiSelect v-model="issueSource" :disabled="issueLoading||saving" @change="selectIssueSource"><option value="">{{issueLoading?'Đang tải…':form.issue_mode==='Plan'?'Chọn kế hoạch':'Chọn yêu cầu'}}</option><option v-for="r in issueSources" :key="r.name" :value="r.name">{{r.name}} · {{r.date}}</option></UiSelect></label>
     <p v-if="form.issue_mode!=='Manual'&&!issueLoading&&!issueSources.length" class="stock-source-empty">{{form.issue_mode==='Plan'?'Chưa có kế hoạch đã duyệt trong công ty này.':'Chưa có yêu cầu cấp vật tư đã duyệt trong công ty này.'}}</p>
     <p v-if="issueNote" class="stock-muted">{{issueNote}}</p>
    </section><div class="stock-form-grid"><label>Ngày<UiInput v-model="form.posting_date" type="date" required /></label><label v-if="form.kind==='count'">Loại kiểm kê<UiSelect v-model="form.count_purpose"><option value="Stock Reconciliation">Kiểm kê định kỳ</option><option value="Opening Stock">Tồn đầu kỳ khi bắt đầu</option></UiSelect></label><label v-if="needsSource">Kho xuất<UiSelect v-model="form.source" required><option value="">Chọn kho</option><option v-for="w in data?.warehouses" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label><label v-if="needsTarget">{{form.kind==='count'?'Kho kiểm kê':'Kho nhận'}}<UiSelect v-model="form.target" required><option value="">Chọn kho</option><option v-for="w in data?.warehouses" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label></div><label v-if="form.kind==='issue'" class="stock-receiver">Người nhận vật tư (HRMS)<UiSelect v-model="form.receiver_employee" :required="!form.existing_name||!form.receiver"><option value="">Chọn nhân viên đang làm việc</option><option v-for="employee in hrEmployees" :key="employee.value" :value="employee.value">{{employee.label}}</option></UiSelect><small v-if="form.existing_name&&form.receiver&&!form.receiver_employee">Phiếu cũ: {{form.receiver}}. Chọn một nhân viên HRMS để cập nhật.</small></label><p v-if="form.kind==='issue'&&form.issue_mode!=='Manual'&&issueSource&&!issueLoading&&!form.lines.length" class="stock-source-empty">Nguồn này chưa có nhu cầu vật tư đã duyệt còn được cấp. Không có dòng nào để xuất.</p><div v-for="(row,index) in form.lines" :key="index" class="stock-line"><label>Vật tư<LinkPicker v-model="row.item" :display-value="row.item_name||stocks.find(i=>i.name===row.item)?.item_name||''" :fetch-options="searchItems" :hide-values="true" placeholder="Chọn vật tư…" :readonly="form.kind==='issue'&&form.issue_mode!=='Manual'" required @select="option=>selectStockItem(row,option)" /><small>{{row.item_name||stocks.find(i=>i.name===row.item)?.item_name||'Nhập mã hoặc chọn từ gợi ý'}}</small></label><label>{{form.kind==='count'?'Tồn thực đếm':'Số lượng'}}<UiInput v-model.number="row.qty" type="number" :min="form.kind==='count'||(form.kind==='issue'&&form.issue_mode!=='Manual')?0:0.000001" :max="form.kind==='issue'&&form.issue_mode!=='Manual'?row.remaining_qty:undefined" step="any" required /><small>{{unitLabel(row.uom||stocks.find(i=>i.name===row.item)?.stock_uom)||'Đơn vị tồn kho'}}</small></label><label v-if="form.kind==='receipt'||(form.kind==='count'&&form.count_purpose==='Opening Stock')">Đơn giá ({{money}} / {{unitLabel(row.uom||stocks.find(i=>i.name===row.item)?.stock_uom)||'đơn vị'}})<UiInput v-model.number="row.rate" type="number" min="0" step="any" required/><small>{{cash(Number(row.qty||0)*Number(row.rate||0))}}</small></label><label v-if="form.kind==='issue'">Khu vực / lô sử dụng<UiInput v-model="row.area" maxlength="140" :readonly="form.issue_mode!=='Manual'&&row.fixed_area" placeholder="VD: Khu A / Lô A1" required /><small v-if="form.issue_mode!=='Manual'">Duyệt {{fmt(row.required_qty)}} · Đã cấp/giữ {{fmt(row.allocated_qty)}} · Còn {{fmt(row.remaining_qty)}}</small></label><UiButton variant="ghost" type="button" class="stock-remove" :disabled="form.lines.length===1||saving" aria-label="Xóa dòng vật tư" @click="form.lines.splice(index,1)">✕</UiButton></div><UiButton variant="outline" v-if="form.kind!=='issue'||form.issue_mode==='Manual'" type="button" class="stock-button" :disabled="form.lines.length>=100||saving" @click="form.lines.push({item:'',qty:1,area:'',rate:0})">+ Thêm vật tư</UiButton><section v-if="form.kind==='receipt'" class="receipt-costs"><div class="section-title"><h3>Chi phí nhập kho</h3><UiButton variant="outline" size="sm" :disabled="costLoading||saving||!receiptAccounts.length||form.additional_costs.length>=30" @click="addCost">+ Thêm chi phí</UiButton></div><p v-if="!costLoading&&!receiptAccounts.length" class="stock-muted">Cần quyền đọc tài khoản chi phí của công ty để thêm chi phí.</p><div v-for="(cost,index) in form.additional_costs" :key="index" class="receipt-cost-row"><label>Khoản chi phí<UiInput v-model="cost.description" maxlength="140" required placeholder="Vận chuyển, bốc xếp…"/></label><label>Số tiền ({{money}})<UiInput v-model.number="cost.amount" type="number" min="0.000001" step="any" required/></label><label>Tài khoản chi phí<UiSelect v-model="cost.expense_account" required><option value="">Chọn tài khoản</option><option v-for="account in receiptAccounts" :key="account.name" :value="account.name">{{account.account_name}}</option></UiSelect></label><UiButton variant="ghost" aria-label="Xóa khoản chi phí" :disabled="saving" @click="form.additional_costs.splice(index,1)">×</UiButton></div><p v-if="form.additional_costs.length" class="stock-muted">Phân bổ chi phí theo giá trị vật tư. Cần có đơn giá để tính phân bổ.</p><div class="receipt-totals"><span>Tiền vật tư <strong>{{cash(receiptBasic)}}</strong></span><span>Chi phí <strong>{{cash(receiptCharges)}}</strong></span><span>Tổng giá trị nhập <strong>{{cash(receiptBasic+receiptCharges)}}</strong></span></div></section><label v-if="form.kind!=='count'" class="stock-notes">{{form.kind==='issue'&&form.issue_mode==='Manual'?'Lý do xuất thủ công':'Ghi chú'}}<UiTextarea v-model="form.notes" maxlength="2000" :required="form.kind==='issue'&&form.issue_mode==='Manual'" placeholder="Mục đích cấp vật tư…"></UiTextarea></label><footer><UiButton variant="default" type="submit" class="stock-button primary" :disabled="saving||issueLoading||!form.lines.length">{{saving?'Đang lưu…':form.existing_name?'Lưu thay đổi':'Lưu phiếu nháp →'}}</UiButton></footer></form>
  </dialog>
  <dialog @click="dismissOnBackdrop($event,masterBusy)" ref="masterDialog" class="stock-dialog stock-master-dialog" @cancel="masterError=''">
   <form @submit.prevent="saveMaster"><header><div><h2>{{masterEditing?masterTitles[masterKind].replace('Thêm','Sửa'):masterTitles[masterKind]}}</h2></div><UiButton variant="outline" type="button" class="stock-button" aria-label="Đóng form danh mục" :disabled="masterBusy" @click="masterDialog.close()">✕</UiButton></header>
    <div v-if="masterDeleting" class="delete-confirm"><p>Xóa danh mục này? Hệ thống chỉ cho xóa khi chưa được sử dụng.</p><label v-if="masterKind==='warehouse'&&(masterEditing?.default_item_count||masterEditing?.stock_default)" class="stock-confirm"><input v-model="masterClearDefaults" type="checkbox">Gỡ kho mặc định của {{masterEditing?.default_item_count||0}} vật tư{{masterEditing?.stock_default?' và thiết lập kho chung':''}} trước khi xóa</label><UiButton variant="outline" @click="masterDeleting=false">Giữ lại</UiButton><UiButton variant="destructive" :disabled="masterBusy||(masterKind==='warehouse'&&(masterEditing?.default_item_count||masterEditing?.stock_default)&&!masterClearDefaults)" @click="deleteMaster">Xác nhận xóa</UiButton></div><p v-if="masterError" role="alert" class="stock-error">{{masterError}}</p>
    <fieldset class="stock-master-fields" :disabled="masterBusy||(masterEditing&&!masterEditing.can_write)"><label v-if="masterKind==='item'">Mã vật tư<UiInput :readonly="!!masterEditing" v-model="master.code" maxlength="140" placeholder="VD: PB-NPK-001" required /></label><label>{{masterKind==='item'?'Tên vật tư':masterKind==='group'?'Tên nhóm vật tư':'Tên kho'}}<UiInput v-model="master.name" maxlength="140" :placeholder="masterKind==='item'?'VD: Phân NPK 16-16-8':masterKind==='group'?'VD: Phân bón':'VD: Kho phân bón farm'" required /></label>
     <template v-if="masterKind==='item'"><label>Nhóm vật tư<UiSelect v-model="master.group" :required="!master.new_group" :disabled="!!master.new_group"><option value="">Chọn nhóm</option><option v-for="g in catalog.groups" :key="g.name" :value="g.name">{{g.name}}</option></UiSelect></label><label v-if="!masterEditing&&session?.permissions['Item Group']">Hoặc tạo nhóm mới<UiInput v-model="master.new_group" maxlength="140" placeholder="Để trống nếu dùng nhóm đã có" /></label><label>Đơn vị tính<UiSelect v-model="master.uom" required><option value="">Chọn đơn vị</option><optgroup label="Thường dùng"><option v-for="name in popularUoms" :key="name" :value="name">{{commonUnits[name]}}</option></optgroup><optgroup label="Đơn vị khác"><option v-for="u in catalog.uoms.filter(u=>!commonUnits[u.name])" :key="u.name" :value="u.name">{{unitLabel(u.name)}}</option></optgroup></UiSelect></label><label>Kho áp dụng tồn tối thiểu<UiSelect v-model="master.minimum_warehouse" @change="master.minimum_stock=masterEditing?.minimum_levels[master.minimum_warehouse]||0"><option v-for="store in data?.warehouses" :key="store.name" :value="store.name">{{store.warehouse_name}}</option></UiSelect></label><label>Tồn tối thiểu ({{unitLabel(master.uom)}})<UiInput v-model.number="master.minimum_stock" type="number" min="0" step="any" required/></label><label>Ghi chú (không bắt buộc)<UiTextarea v-model="master.description" maxlength="2000" placeholder="Quy cách đóng gói, thông tin nhận biết…"></UiTextarea></label></template>
     <label v-if="!masterEditing&&masterKind==='group'&&catalog.groups.filter(g=>g.is_group).length>1">Nhóm cha<UiSelect v-model="master.parent" required><option v-for="g in catalog.groups.filter(g=>g.is_group)" :key="g.name" :value="g.name">{{g.name}}</option></UiSelect></label>
     <template v-if="masterKind==='warehouse'">
      <label>Mã kho (tự sinh theo tên)<UiInput :model-value="warehouseCode" readonly/><small>Mã theo tên kho và viết tắt công ty; khi đổi tên kho, ERPNext cập nhật liên kết liên quan.</small></label>
      <label>Địa chỉ kho / điểm nhận hàng<UiTextarea v-model="master.lotus_address" maxlength="500" placeholder="Địa chỉ giao hàng, xã, tỉnh, hướng dẫn đến cổng kho"/></label>
      <label>Người phụ trách kho (nhân sự HRMS)<UiSelect v-model="master.lotus_contact_employee"><option value="">Chưa phân công</option><option v-for="employee in hrEmployees" :key="employee.value" :value="employee.value">{{employee.label}}</option></UiSelect><small v-if="master.lotus_contact_employee">{{employeeName(master.lotus_contact_employee)}}</small><small v-if="!hrEmployees.length">Chưa có nhân sự đang làm việc, cần tiếp nhận tại module Nhân sự.</small></label>
      <label>Số điện thoại người phụ trách<UiInput :model-value="master.lotus_contact_phone" readonly placeholder="Tự lấy từ hồ sơ HRMS"/><small>Đồng bộ theo hồ sơ nhân sự khi lưu; không nhập thủ công.</small></label>
      <label>Giờ nhận hàng<UiInput v-model="master.lotus_receiving_hours" maxlength="140" placeholder="Ví dụ: Thứ Hai–Thứ Bảy, 7:00–17:00"/></label>
      <label>Thời gian chờ hàng mặc định (ngày)<UiInput v-model.number="master.lotus_default_lead_days" type="number" min="0" max="365" step="1"/><small>Chỉ dùng để gợi ý, ngày giao do NCC xác nhận sẽ được ưu tiên.</small></label>
      <label>Ghi chú giao nhận<UiTextarea v-model="master.lotus_delivery_note" maxlength="500" placeholder="Cổng giao hàng, giờ nghỉ, yêu cầu bốc dỡ…"/></label>
     </template>
     <label v-if="!masterEditing&&masterKind==='warehouse'&&catalog.parents.length>1">Thuộc nhóm kho<UiSelect v-model="master.parent" required><option value="">Chọn nhóm kho</option><option v-for="w in catalog.parents" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label>
    </fieldset><footer><UiButton v-if="masterEditing?.can_delete" variant="destructive" :disabled="masterBusy" @click="masterDeleting=true">Xóa danh mục</UiButton><UiButton v-if="!masterEditing||masterEditing.can_write" variant="default" type="submit" class="stock-button primary" :disabled="masterBusy">{{masterBusy?'Đang lưu…':'Lưu '+(masterKind==='item'?'vật tư':masterKind==='group'?'nhóm':'kho')}}</UiButton></footer>
   </form>
  </dialog>
  <dialog @click="dismissOnBackdrop($event,posting)" ref="detailDialog" class="stock-dialog" @cancel="detailError=''">
   <form v-if="detail" @submit.prevent="postDocument"><header><div><h2>{{detail.name}}</h2></div><UiButton variant="outline" type="button" class="stock-button" aria-label="Đóng chi tiết phiếu" :disabled="posting" @click="detailDialog.close()">✕</UiButton></header><div class="actions"><a :href="printURL(detail.doctype,detail.name)" target="_blank" rel="noopener" class="stock-button">In phiếu</a></div><div v-if="detail.docstatus===0" class="actions"><UiButton v-if="detail.can_write&&(detail.kind!=='Material Issue'||!detail.issue_mode||detail.issue_mode==='Manual')" variant="outline" :disabled="posting" @click="editDocument">Sửa phiếu nháp</UiButton><UiButton v-if="detail.can_delete" variant="destructive" :disabled="posting" @click="draftDeleting=true">Xóa phiếu nháp</UiButton></div><div v-if="draftDeleting" class="delete-confirm"><span>Xác nhận xóa phiếu nháp?</span><UiButton variant="outline" @click="draftDeleting=false">Giữ lại</UiButton><UiButton variant="destructive" :disabled="posting" @click="deleteDraft">Xác nhận xóa</UiButton></div><p class="stock-muted">{{type(detail.kind)}} · {{detail.posting_date}} · {{detail.company}} · {{status(detail.docstatus)}}</p><p v-if="detailError" class="stock-error" role="alert">{{detailError}}</p><p v-if="detail.docstatus===1" class="stock-success" role="status">Phiếu đã ghi sổ. Tồn kho đã được cập nhật.</p>
   <DataTable :rows="detail.items" :columns="detail.kind==='Material Receipt'?[...detailColumns,...receiptDetailColumns]:detailColumns" /><template v-if="detail.kind==='Material Receipt'"><div class="receipt-totals"><span>Tiền vật tư <strong>{{cash(detail.basic_total)}}</strong></span><span>Chi phí <strong>{{cash(detail.additional_total)}}</strong></span><span>Giá trị nhập <strong>{{cash(detail.incoming_total)}}</strong></span></div><div v-if="detail.additional_costs?.length" class="receipt-detail-costs"><div v-for="(cost,index) in detail.additional_costs" :key="index"><span>{{cost.description}}</span><strong>{{cash(cost.amount)}}</strong></div></div><p class="stock-muted">Giá trị nhập gồm chi phí phân bổ. Công nợ nhà cung cấp ghi nhận bằng hóa đơn mua hàng.</p></template><p v-if="detail.receiver" class="stock-muted">Người nhận: {{detail.receiver}} · {{issueTabs[detail.issue_mode]}}</p><p v-if="detail.notes" class="stock-muted">{{detail.notes}}</p>
   <footer v-if="detail.can_submit"><label class="stock-confirm"><input v-model="confirmPost" type="checkbox" required> Tôi đã kiểm tra phiếu. Ghi sổ sẽ cập nhật tồn kho.</label><UiButton variant="default" type="submit" class="stock-button primary" :disabled="posting||!confirmPost">{{posting?'Đang ghi sổ…':'Ghi sổ phiếu'}}</UiButton></footer><p v-else-if="detail.docstatus===0" class="stock-muted">Tài khoản chưa có quyền ghi sổ hoặc phiếu thuộc nghiệp vụ nâng cao chưa hỗ trợ ở đây.</p>
   </form>
  </dialog>
 </div>
</template>
